class StabilityTests {
 static void Check(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("PASS: "+name);}
 static void Pump(int ms){var until=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(5);}}
 static void Until(Func<bool> ready,int seconds=15){var until=DateTime.UtcNow.AddSeconds(seconds);while(!ready()&&DateTime.UtcNow<until)Pump(10);Check(ready(),"operation completed within deadline");}
 sealed class Server:IDisposable {
  readonly TcpListener listener=new TcpListener(IPAddress.Loopback,0);readonly byte[] png;volatile bool stopped;public int Count,Delay=350,Status=200;public string Url;
  public Server(){using(var bmp=new Bitmap(256,256)){using(var g=Graphics.FromImage(bmp))g.Clear(Color.FromArgb(128,120,0));using(var memory=new MemoryStream()){bmp.Save(memory,System.Drawing.Imaging.ImageFormat.Png);png=memory.ToArray();}}listener.Start();Url="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/{z}/{x}/{y}.png";Task.Run(delegate{while(!stopped)try{var client=listener.AcceptTcpClient();Task.Run(()=>Reply(client));}catch(SocketException){break;}});}
  void Reply(TcpClient client){try{using(client)using(var stream=client.GetStream()){var header=new StringBuilder();while(!header.ToString().EndsWith("\r\n\r\n")){int value=stream.ReadByte();if(value<0)return;header.Append((char)value);}Interlocked.Increment(ref Count);Thread.Sleep(Delay);byte[] response=Encoding.ASCII.GetBytes("HTTP/1.1 "+Status+" Test\r\nContent-Length: "+png.Length+"\r\nConnection: close\r\n\r\n");stream.Write(response,0,response.Length);stream.Write(png,0,png.Length);}}catch(IOException){}catch(ObjectDisposedException){}}
  public void Dispose(){stopped=true;listener.Stop();}
 }
 static void Settings(string root){string path=Path.Combine(root,"view-settings.xml");var settings=new ViewSettings{CardOpacity=40};settings.Save(path);settings.CardOpacity=70;settings.Save(path);File.WriteAllText(path,"<broken>");Check(ViewSettings.Load(path).CardOpacity==40,"corrupt primary recovers validated backup");settings.CardOpacity=80;settings.Save(path);Check(ViewSettings.Load(path+".bak").CardOpacity==40,"recovery save preserves healthy backup");byte[] before=File.ReadAllBytes(path);bool failed=false;try{AtomicSettings.Save(path,stream=>{stream.WriteByte(42);throw new IOException("injected write failure");});}catch(IOException){failed=true;}Check(failed&&File.ReadAllBytes(path).SequenceEqual(before),"partial write preserves previous data");using(var locked=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.None)){failed=false;try{settings.Save(path);}catch(IOException){failed=true;}Check(failed,"locked destination is reported as failure");}Check(File.ReadAllBytes(path).SequenceEqual(before)&&Directory.GetFiles(root,"*.tmp").Length==0,"failed replacement leaves no temp and no data loss");failed=false;try{DiskSpace.Check(path,Int64.MaxValue/2);}catch(IOException){failed=true;}Check(failed,"insufficient disk budget rejected without deleting files");}
 static void Logs(string root){Diagnostics.Initialize(root);for(int i=0;i<4500;i++)Diagnostics.Record("test.error",new IOException("secret=API_PRIVATE_KEY; 55.751,37.621 C:\\private"));string report=Diagnostics.Report();Check(!report.Contains("API_PRIVATE_KEY")&&!report.Contains("55.751")&&!report.Contains("private")&&report.Contains("HRESULT")&&report.Contains("0.40"),"diagnostics excludes secrets and locations, keeps version and error codes");var files=Directory.GetFiles(Path.Combine(root,"diagnostics"));Check(files.Length<=2&&files.Sum(f=>new FileInfo(f).Length)<2L*Diagnostics.MaxBytes+2048,"diagnostics rotation bounded to two files");}
 static void Network(string root){using(var server=new Server()){var source=new MapSource{Id="stability",Name="Test",Template=server.Url,MinZoom=0,MaxZoom=18};string cache=Path.Combine(root,"shared");using(var a=new TileStore(cache,null,source))using(var b=new TileStore(cache,null,source))using(var cancel=new CancellationTokenSource()){a.OnlineEnabled=b.OnlineEnabled=true;a.ForceDiskCache=b.ForceDiskCache=true;var first=a.SaveOfflineTile(3,4,5,cancel.Token);var second=b.SaveOfflineTile(3,4,5,CancellationToken.None);Thread.Sleep(80);cancel.Cancel();bool canceled=false;try{first.GetAwaiter().GetResult();}catch(OperationCanceledException){canceled=true;}Check(canceled&&second.GetAwaiter().GetResult()&&server.Count==1,"two consumers share one request; cancelling one preserves the other");}
  using(var observer=new TileStore(cache,null,source)){observer.GetTile(3,4,6);Until(()=>observer.PendingCount==0);using(var writer=new TileStore(cache,null,source)){writer.OnlineEnabled=true;writer.ForceDiskCache=true;Check(writer.SaveOfflineTile(3,4,6,CancellationToken.None).Result,"second window persists tile");}Image image=null;Until(()=>{image=observer.GetTile(3,4,6);return image!=null;});image.Dispose();Check(true,"disk event invalidates other window negative cache immediately");}
  string broken=Path.Combine(cache,"3","4","6.png");File.WriteAllText(broken,"broken DEM");using(var writer=new TileStore(cache,null,source)){writer.OnlineEnabled=true;writer.ForceDiskCache=true;int requests=server.Count;Check(writer.SaveOfflineTile(3,4,6,CancellationToken.None).Result&&server.Count==requests+1,"corrupted cached image is repaired");server.Status=503;Check(!writer.SaveOfflineTile(3,4,7,CancellationToken.None).Result&&!File.Exists(Path.Combine(cache,"3","4","7.png")),"HTTP failure never creates a successful cached tile");}
  Until(()=>TileNetwork.PendingCount==0);Check(true,"shared requests released after completion");
  var area=new OfflineArea{Source=source,Lat1=10,Lon1=20,Lat2=10.001,Lon2=20.001,Min=3,Max=4,Total=3,Done=1,State="Загрузка"};OfflineAreaCatalog.Update(root,area);var restored=OfflineAreaCatalog.Load(root).Areas.Single();Check(restored.Id==area.Id&&restored.Done==1&&restored.Min==3&&restored.Source.Template==source.Template,"offline area checkpoint survives restart with source and detail levels");
 }}
 static void Render(){var bytes=new byte[64*64*4];for(int i=3;i<bytes.Length;i+=4)bytes[i]=255;var input=new VisibilityScreenInput{Width=2560,Height=1440,Size=64,Source=bytes,Left=0,Top=0,Right=GeoMath.WorldSize(14),Bottom=GeoMath.WorldSize(14),Zoom=4,CenterX=2048,CenterY=2048,Opacity=45};var watch=System.Diagnostics.Stopwatch.StartNew();using(var image=input.Render(CancellationToken.None))Check(image.Width==2560&&image.Height==1440,"worker renders full 2560x1440 viewport");Console.WriteLine("REPROJECT 2560x1440 ms="+watch.ElapsedMilliseconds);for(int i=0;i<60;i++)using(var cancellation=new CancellationTokenSource()){var work=BackgroundJobs.Run("test.render",()=>input.Render(cancellation.Token));cancellation.Cancel();try{using(var image=work.GetAwaiter().GetResult()){} }catch(OperationCanceledException){}}Until(()=>BackgroundJobs.Count==0);Check(true,"60 canceled reprojections release all tracked jobs");}
 static void Close(string root){using(var barrier=new ManualResetEventSlim(false))using(var form=new MainForm(null,false,Path.Combine(root,"close"))){form.Show();Pump(100);typeof(MainForm).GetField("dirty",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(form,true);BackgroundJobs.Run("test.slow-disk",()=>barrier.Wait());form.Close();Pump(120);Check(!form.IsDisposed,"closing awaits outstanding work without blocking UI event pump");barrier.Set();Until(()=>form.IsDisposed);Check(File.Exists(Path.Combine(root,"close","workspace.gpx"))&&File.Exists(Path.Combine(root,"close","preferences.xml")),"asynchronous close completes workspace and settings save");}}

 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern int GetGuiResources(IntPtr process,int flag);
 static void Soak(string root){
  var process=System.Diagnostics.Process.GetCurrentProcess();int before=GetGuiResources(process.Handle,0);long memoryBefore=GC.GetTotalMemory(true);var durations=new System.Collections.Generic.List<double>();int cycles=0;
  using(var store=new TileStore(Path.Combine(root,"soak"),null))using(var map=new MapCanvas(store){Dock=DockStyle.Fill})using(var window=new Form{ClientSize=new Size(1600,1000)}){
   window.Controls.Add(map);map.Settings.Gpu=false;window.Show();var origin=new GeoPoint(0,0);map.GoTo(origin,14);var grid=VisibilityGrid.Create(origin,new VisibilityOptions{Radius=1000,Quality=0},CancellationToken.None);for(int i=0;i<grid.Heights.Length;i++)grid.Heights[i]=100;grid.Calculate(CancellationToken.None);map.SetVisibility(VisibilityRaster.Create(grid,CancellationToken.None));var until=DateTime.UtcNow.AddSeconds(30);
   using(var frame=new Bitmap(map.Width,map.Height)){while(DateTime.UtcNow<until){map.Settings.Rotation=cycles%360;map.RequestFrame();var watch=System.Diagnostics.Stopwatch.StartNew();map.DrawToBitmap(frame,map.ClientRectangle);durations.Add(watch.Elapsed.TotalMilliseconds);Pump(20);cycles++;}}
   map.SetVisibility(null);window.Close();
  }
  Until(()=>BackgroundJobs.Count==0);Pump(100);GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();int after=GetGuiResources(process.Handle,0);long memoryAfter=GC.GetTotalMemory(true);durations.Sort();Console.WriteLine("SOAK seconds=30 viewport=1600x1000 rotations="+cycles+" DrawToBitmap p50="+durations[durations.Count/2].ToString("F1")+" p95="+durations[(int)(durations.Count*.95)].ToString("F1")+" ms; GDI before="+before+" after="+after+" managedBefore="+memoryBefore+" managedAfter="+memoryAfter);
  Check(after<=before+15&&BackgroundJobs.Count==0,"continuous viewport changes release GDI resources and background jobs");
 }
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Diagnostics.Initialize(root);Settings(root);Logs(root);Network(root);Render();Close(root);Soak(root);Console.WriteLine("ALL STABILITY 0.38 TESTS PASSED");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
